class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) {
            return false;
        }

        java.util.TreeMap<Integer, Integer> counts = new java.util.TreeMap<>();
        for (int card : hand) {
            counts.merge(card, 1, Integer::sum);
        }

        while (!counts.isEmpty()) {
            int start = counts.firstKey();
            for (int value = start; value < start + groupSize; value++) {
                Integer amount = counts.get(value);
                if (amount == null) {
                    return false;
                }
                if (amount == 1) {
                    counts.remove(value);
                } else {
                    counts.put(value, amount - 1);
                }
            }
        }
        return true;
    }
}

class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) {
            return false;
        }

        java.util.Arrays.sort(hand);
        java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
        for (int card : hand) {
            freq.put(card, freq.getOrDefault(card, 0) + 1);
        }

        for (int card : hand) {
            if (freq.get(card) == 0) {
                continue;
            }
            for (int offset = 0; offset < groupSize; offset++) {
                int value = card + offset;
                int amount = freq.getOrDefault(value, 0);
                if (amount == 0) {
                    return false;
                }
                freq.put(value, amount - 1);
            }
        }
        return true;
    }
}

class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) {
            return false;
        }

        java.util.Arrays.sort(hand);
        java.util.ArrayDeque<Integer> started = new java.util.ArrayDeque<>();
        int openGroups = 0;
        int previous = Integer.MIN_VALUE;

        for (int i = 0; i < hand.length; ) {
            int value = hand[i];
            int count = 0;
            while (i < hand.length && hand[i] == value) {
                count++;
                i++;
            }

            if (openGroups > 0 && value != previous + 1) {
                return false;
            }
            if (count < openGroups) {
                return false;
            }

            started.offerLast(count - openGroups);
            openGroups = count;
            if (started.size() == groupSize) {
                openGroups -= started.pollFirst();
            }
            previous = value;
        }

        return openGroups == 0;
    }
}

class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) {
            return false;
        }

        java.util.TreeMap<Integer, Integer> counts = new java.util.TreeMap<>();
        for (int card : hand) {
            counts.put(card, counts.getOrDefault(card, 0) + 1);
        }

        while (!counts.isEmpty()) {
            int start = counts.firstKey();
            int groups = counts.get(start);
            for (int value = start; value < start + groupSize; value++) {
                Integer amount = counts.get(value);
                if (amount == null || amount < groups) {
                    return false;
                }
                if (amount == groups) {
                    counts.remove(value);
                } else {
                    counts.put(value, amount - groups);
                }
            }
        }
        return true;
    }
}

class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) {
            return false;
        }
        if (groupSize == 1) {
            return true;
        }

        java.util.Arrays.sort(hand);
        java.util.PriorityQueue<int[]> groups = new java.util.PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]);
            }
            return Integer.compare(a[1], b[1]);
        });

        for (int card : hand) {
            if (!groups.isEmpty() && groups.peek()[0] + 1 < card) {
                return false;
            }
            if (!groups.isEmpty() && groups.peek()[0] + 1 == card) {
                int[] group = groups.poll();
                group[0] = card;
                group[1]++;
                if (group[1] < groupSize) {
                    groups.offer(group);
                }
            } else {
                groups.offer(new int[] {card, 1});
            }
        }

        return groups.isEmpty();
    }
}
